query AleoMessages($limit: Int!, $offset: Int!, $where: message_view_bool_exp!) {
  message_view(
    where: $where
    order_by: [{send_occurred_at: desc}, {id: desc}]
    limit: $limit
    offset: $offset
  ) {
    msg_id
    id
    origin_domain_id
    destination_domain_id
    sender
    recipient
    origin_tx_sender
    origin_tx_hash
    message_body
    send_occurred_at
  }
  domain { id name }
}
